(12606,1,'2026-04-21 18:33:47','2026-04-21 16:33:47','<!-- wp:group {\"tagName\":\"main\",\"className\":\"iss-rental-page\",\"layout\":{\"type\":\"default\"}} -->\n<main class=\"wp-block-group iss-rental-page\"><!-- wp:cover {\"url\":\"/wp-content/uploads/2026/05/rental1-1024x695.png\",\"id\":13313,\"dimRatio\":55,\"customOverlayColor\":\"#996032\",\"isUserOverlayColor\":false,\"focalPoint\":{\"x\":0.6,\"y\":0.54},\"minHeight\":68,\"minHeightUnit\":\"vh\",\"sizeSlug\":\"large\",\"align\":\"full\",\"className\":\"iss-rental-hero\"} -->\n<div class=\"wp-block-cover alignfull iss-rental-hero\" style=\"min-height:68vh\"><img class=\"wp-block-cover__image-background wp-image-13313 size-large\" alt=\"\" src=\"/wp-content/uploads/2026/05/rental1-1024x695.png\" style=\"object-position:60% 54%\" data-object-fit=\"cover\" data-object-position=\"60% 54%\"/><span aria-hidden=\"true\" class=\"wp-block-cover__background has-background-dim-60 has-background-dim\" style=\"background-color:#996032\"></span><div class=\"wp-block-cover__inner-container\"><!-- wp:group {\"className\":\"iss-container iss-rental-hero__inner\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group iss-container iss-rental-hero__inner\"><!-- wp:group {\"className\":\"iss-heading iss-heading\\u002d\\u002duncaged\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group iss-heading iss-heading--uncaged\"><!-- wp:paragraph {\"className\":\"iss-kicker iss-kicker\\u002d\\u002dlight iss-kicker\\u002d\\u002dlg\"} -->\n<p class=\"iss-kicker iss-kicker--light iss-kicker--lg\">Raum für</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":1,\"className\":\"iss-rental-hero__title\"} -->\n<h1 class=\"wp-block-heading iss-rental-hero__title\">Anlässe und Begegnungen</h1>\n<!-- /wp:heading -->\n\n<!-- wp:buttons {\"className\":\"iss-rental-hero__actions\"} -->\n<div class=\"wp-block-buttons iss-rental-hero__actions\"><!-- wp:button {\"className\":\"is-style-fill\"} -->\n<div class=\"wp-block-button is-style-fill\"><a class=\"wp-block-button__link wp-element-button\" href=\"#anfrage\">Anfrage stellen</a></div>\n<!-- /wp:button -->\n\n<!-- wp:button {\"backgroundColor\":\"vaporous-white\",\"textColor\":\"eerie-black\",\"className\":\"is-style-outline iss-rental-hero__secondary\"} -->\n<div class=\"wp-block-button is-style-outline iss-rental-hero__secondary\"><a class=\"wp-block-button__link has-eerie-black-color has-vaporous-white-background-color has-text-color has-background wp-element-button\" href=\"#moeglichkeiten\">Möglichkeiten ansehen</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div></div>\n<!-- /wp:cover -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"section iss-rental-intro\",\"layout\":{\"type\":\"constrained\"}} -->\n<section class=\"wp-block-group section iss-rental-intro\"><!-- wp:group {\"className\":\"iss-container\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group iss-container\"><!-- wp:columns {\"verticalAlignment\":\"top\",\"className\":\"iss-rental-intro__grid\"} -->\n<div class=\"wp-block-columns are-vertically-aligned-top iss-rental-intro__grid\"><!-- wp:column {\"verticalAlignment\":\"top\",\"width\":\"60%\"} -->\n<div class=\"wp-block-column is-vertically-aligned-top\" style=\"flex-basis:60%\"><!-- wp:group {\"className\":\"iss-heading\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group iss-heading\"><!-- wp:paragraph {\"className\":\"iss-kicker\"} -->\n<p class=\"iss-kicker\">Raum mit Charakter</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"className\":\"iss-heading__title\"} -->\n<h2 class=\"wp-block-heading iss-heading__title\">Für Formate, die mehr brauchen als einen neutralen Mietraum.</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"iss-heading__text\"} -->\n<p class=\"iss-heading__text\">Wer im Industriesalon mietet, bekommt keinen anonymen Veranstaltungsraum. Der Ort bringt Geschichte, Materialität und Atmosphäre bereits mit. Das macht ihn besonders passend für Veranstaltungen, die in Erinnerung bleiben sollen und einen glaubwürdigen Rahmen brauchen.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Ob kleiner Empfang, interner Workshop, Pressegespräch, Lesung, Gesprächsabend, Ausstellungseröffnung oder ein sorgfältig geplanter privater Anlass: Der Salon bietet einen ruhigen, markanten Rahmen direkt in Oberschöneweide. Je nach Anlass lässt sich die Nutzung sachlich, kulturell oder gastlich anlegen.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"verticalAlignment\":\"top\",\"width\":\"40%\"} -->\n<div class=\"wp-block-column is-vertically-aligned-top\" style=\"flex-basis:40%\"><!-- wp:group {\"className\":\"iss-rental-facts\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group iss-rental-facts\"><!-- wp:group {\"className\":\"iss-card iss-card\\u002d\\u002dinfo iss-card\\u002d\\u002dflat iss-card\\u002d\\u002dbrown\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group iss-card iss-card--info iss-card--flat iss-card--brown\"><!-- wp:group {\"className\":\"iss-card__body\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group iss-card__body\"><!-- wp:paragraph {\"className\":\"iss-kicker iss-kicker\\u002d\\u002dcompact\"} -->\n<p class=\"iss-kicker iss-kicker--compact\">Auf einen Blick</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":3,\"className\":\"iss-card__title\"} -->\n<h3 class=\"wp-block-heading iss-card__title\">Gut geeignet für</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"iss-card__text\"} -->\n<p class=\"iss-card__text\">Empfänge, Vorträge, kleinere Tagungen, Vereinsabende, Kulturformate, Präsentationen, Gesprächsrunden und ausgewählte Feiern.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"iss-card iss-card\\u002d\\u002dinfo iss-card\\u002d\\u002dflat iss-card\\u002d\\u002dblue\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group iss-card iss-card--info iss-card--flat iss-card--blue\"><!-- wp:group {\"className\":\"iss-card__body\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group iss-card__body\"><!-- wp:paragraph {\"className\":\"iss-kicker iss-kicker\\u002d\\u002dcompact\"} -->\n<p class=\"iss-kicker iss-kicker--compact\">Lage</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":3,\"className\":\"iss-card__title\"} -->\n<h3 class=\"wp-block-heading iss-card__title\">Mitten in Schöneweide</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"iss-card__text\"} -->\n<p class=\"iss-card__text\">Ein besonderer Ort am historischen Industriestandort mit eigener Geschichte und guter Anbindung im Berliner Südosten.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"iss-card iss-card\\u002d\\u002dinfo iss-card\\u002d\\u002dflat iss-card\\u002d\\u002dgreen\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group iss-card iss-card--info iss-card--flat iss-card--green\"><!-- wp:group {\"className\":\"iss-card__body\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group iss-card__body\"><!-- wp:paragraph {\"className\":\"iss-kicker iss-kicker\\u002d\\u002dcompact\"} -->\n<p class=\"iss-kicker iss-kicker--compact\">Anfrage</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":3,\"className\":\"iss-card__title\"} -->\n<h3 class=\"wp-block-heading iss-card__title\">Individuell abgestimmt</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"iss-card__text\"} -->\n<p class=\"iss-card__text\">Nutzung, Umfang, Zeiten und Begleitprogramm werden passend zum Anlass besprochen. So bleibt der Rahmen stimmig und realistisch planbar.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group --></section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"section section\\u002d\\u002dalt section\\u002d\\u002dwith-rail iss-rental-uses\",\"layout\":{\"type\":\"constrained\"}} -->\n<section id=\"moeglichkeiten\" class=\"wp-block-group section section--alt section--with-rail iss-rental-uses\"><!-- wp:group {\"className\":\"iss-container\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group iss-container\"><!-- wp:group {\"className\":\"iss-heading\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group iss-heading\"><!-- wp:paragraph {\"className\":\"iss-kicker iss-kicker\\u002d\\u002dbrown\"} -->\n<p class=\"iss-kicker iss-kicker--brown\">Möglichkeiten</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"className\":\"iss-heading__title\"} -->\n<h2 class=\"wp-block-heading iss-heading__title\">Typische Nutzungen des Salons.</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"iss-heading__text\"} -->\n<p class=\"iss-heading__text\">Nicht jeder Anlass braucht dieselbe Dramaturgie. Deshalb ist der Salon nicht als starres Paket gedacht, sondern als Raum, der auf unterschiedliche Formate zugeschnitten werden kann.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"iss-card-grid iss-rental-uses__grid\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-card-grid iss-rental-uses__grid\"><!-- wp:group {\"className\":\"iss-card iss-rental-usage-card iss-card\\u002d\\u002dbrown\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group iss-card iss-rental-usage-card iss-card--brown\"><!-- wp:image {\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"className\":\"iss-card__media\"} -->\n<figure class=\"wp-block-image size-full iss-card__media\"><img src=\"/wp-content/uploads/2026/04/salon-empfang.jpg\" alt=\"Empfang im Salon\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:group {\"className\":\"iss-card__body\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group iss-card__body\"><!-- wp:paragraph {\"className\":\"iss-kicker iss-kicker\\u002d\\u002dcompact iss-kicker\\u002d\\u002dbrown\"} -->\n<p class=\"iss-kicker iss-kicker--compact iss-kicker--brown\">Empfang</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":3,\"className\":\"iss-card__title\"} -->\n<h3 class=\"wp-block-heading iss-card__title\">Abende, Treffen, kleine Feiern</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"iss-card__text\"} -->\n<p class=\"iss-card__text\">Für Anlässe mit persönlicher Atmosphäre: Empfang, Jubiläum, kleiner Festabend oder ein bewusst gesetztes Zusammenkommen in besonderem Rahmen.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"iss-card iss-rental-usage-card iss-card\\u002d\\u002dblue\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group iss-card iss-rental-usage-card iss-card--blue\"><!-- wp:image {\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"className\":\"iss-card__media\"} -->\n<figure class=\"wp-block-image size-full iss-card__media\"><img src=\"/wp-content/uploads/2026/04/salon-vortrag.jpg\" alt=\"Vortrag oder Diskussion\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:group {\"className\":\"iss-card__body\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group iss-card__body\"><!-- wp:paragraph {\"className\":\"iss-kicker iss-kicker\\u002d\\u002dcompact iss-kicker\\u002d\\u002dblue\"} -->\n<p class=\"iss-kicker iss-kicker--compact iss-kicker--blue\">Diskurs</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":3,\"className\":\"iss-card__title\"} -->\n<h3 class=\"wp-block-heading iss-card__title\">Vorträge, Panels, Gespräche</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"iss-card__text\"} -->\n<p class=\"iss-card__text\">Für Themen, die einen eigenständigen Ort brauchen: Lesung, Podium, Gesprächsabend, Presseformat, Präsentation oder moderierter Austausch.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"iss-card iss-rental-usage-card iss-card\\u002d\\u002dgreen\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group iss-card iss-rental-usage-card iss-card--green\"><!-- wp:image {\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"className\":\"iss-card__media\"} -->\n<figure class=\"wp-block-image size-full iss-card__media\"><img src=\"/wp-content/uploads/2026/04/salon-workshop.jpg\" alt=\"Workshop im Salon\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:group {\"className\":\"iss-card__body\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group iss-card__body\"><!-- wp:paragraph {\"className\":\"iss-kicker iss-kicker\\u002d\\u002dcompact iss-kicker\\u002d\\u002dgreen\"} -->\n<p class=\"iss-kicker iss-kicker--compact iss-kicker--green\">Arbeit</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":3,\"className\":\"iss-card__title\"} -->\n<h3 class=\"wp-block-heading iss-card__title\">Workshops, Klausuren, interne Formate</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"iss-card__text\"} -->\n<p class=\"iss-card__text\">Für Teams, Initiativen und Organisationen, die abseits standardisierter Seminarhotels zusammenkommen möchten.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"section iss-rental-qualities\",\"layout\":{\"type\":\"constrained\"}} -->\n<section class=\"wp-block-group section iss-rental-qualities\"><!-- wp:group {\"className\":\"iss-container\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group iss-container\"><!-- wp:columns {\"verticalAlignment\":\"top\",\"className\":\"iss-rental-qualities__grid\"} -->\n<div class=\"wp-block-columns are-vertically-aligned-top iss-rental-qualities__grid\"><!-- wp:column {\"verticalAlignment\":\"top\",\"width\":\"42%\"} -->\n<div class=\"wp-block-column is-vertically-aligned-top\" style=\"flex-basis:42%\"><!-- wp:image {\"sizeSlug\":\"large\",\"className\":\"iss-rental-qualities__image\"} -->\n<figure class=\"wp-block-image size-large iss-rental-qualities__image\"><img src=\"/wp-content/uploads/2026/04/salon-detail.jpg\" alt=\"Detailansicht des Salons\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"verticalAlignment\":\"top\",\"width\":\"58%\"} -->\n<div class=\"wp-block-column is-vertically-aligned-top\" style=\"flex-basis:58%\"><!-- wp:group {\"className\":\"iss-heading\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group iss-heading\"><!-- wp:paragraph {\"className\":\"iss-kicker iss-kicker\\u002d\\u002dblue\"} -->\n<p class=\"iss-kicker iss-kicker--blue\">Warum hier</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"className\":\"iss-heading__title\"} -->\n<h2 class=\"wp-block-heading iss-heading__title\">Ein Ort, der einer Veranstaltung sofort Profil gibt.</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"iss-heading__text\"} -->\n<p class=\"iss-heading__text\">Viele Räume funktionieren technisch, bleiben aber austauschbar. Der Salon ist anders: Er hat Präsenz, erzählt etwas über den Standort und setzt einen deutlichen Ton, ohne laut zu werden.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:list {\"className\":\"iss-rental-list\"} -->\n<ul class=\"wp-block-list iss-rental-list\"><!-- wp:list-item -->\n<li>historischer Kontext statt neutraler Eventkulisse</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>geeignet für kulturelle, institutionelle und nachbarschaftliche Formate</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>glaubwürdiger Rahmen für Inhalte mit Bezug zu Stadt, Industrie, Geschichte oder Gemeinschaft</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>persönlich, konzentriert und kleiner als klassische Veranstaltungshäuser</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>auf Wunsch kombinierbar mit Führung oder thematischem Bezug zum Haus</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>Gerade für Organisationen, Initiativen, Unternehmen, Stiftungen oder Privatpersonen, die einen besonderen Berliner Ort suchen, kann das den Unterschied machen. Der Raum ist nicht bloß Hintergrund, sondern Teil des Eindrucks.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group --></section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"section section\\u002d\\u002dalt iss-rental-process\",\"layout\":{\"type\":\"constrained\"}} -->\n<section class=\"wp-block-group section section--alt iss-rental-process\"><!-- wp:group {\"className\":\"iss-container\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group iss-container\"><!-- wp:group {\"className\":\"iss-heading\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group iss-heading\"><!-- wp:paragraph {\"className\":\"iss-kicker iss-kicker\\u002d\\u002dgreen\"} -->\n<p class=\"iss-kicker iss-kicker--green\">Ablauf</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"className\":\"iss-heading__title\"} -->\n<h2 class=\"wp-block-heading iss-heading__title\">So läuft eine Anfrage ab.</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"iss-heading__text\"} -->\n<p class=\"iss-heading__text\">Damit Aufwand und Erwartungen zusammenpassen, klären wir Anlass, Umfang und gewünschte Nutzung vorab. So lässt sich früh einschätzen, ob der Salon der richtige Ort ist.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:columns {\"verticalAlignment\":\"top\",\"className\":\"iss-rental-steps\"} -->\n<div class=\"wp-block-columns are-vertically-aligned-top iss-rental-steps\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"className\":\"iss-rental-step\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group iss-rental-step\"><!-- wp:paragraph {\"className\":\"iss-rental-step__number\"} -->\n<p class=\"iss-rental-step__number\">01</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":3,\"className\":\"iss-rental-step__title\"} -->\n<h3 class=\"wp-block-heading iss-rental-step__title\">Anlass skizzieren</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Worum geht es, wie viele Personen sind geplant, welcher Rahmen wird gesucht und zu welchem Zeitpunkt soll die Veranstaltung stattfinden?</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"className\":\"iss-rental-step\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group iss-rental-step\"><!-- wp:paragraph {\"className\":\"iss-rental-step__number\"} -->\n<p class=\"iss-rental-step__number\">02</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":3,\"className\":\"iss-rental-step__title\"} -->\n<h3 class=\"wp-block-heading iss-rental-step__title\">Machbarkeit klären</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Wir prüfen, ob Format, Termin und Umfang zum Haus passen und welche Form der Nutzung sinnvoll und realistisch ist.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"className\":\"iss-rental-step\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group iss-rental-step\"><!-- wp:paragraph {\"className\":\"iss-rental-step__number\"} -->\n<p class=\"iss-rental-step__number\">03</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":3,\"className\":\"iss-rental-step__title\"} -->\n<h3 class=\"wp-block-heading iss-rental-step__title\">Rahmen abstimmen</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Danach werden Nutzung, Zeiten, eventuelle Zusatzwünsche und die nächsten Schritte konkret besprochen.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group --></section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"section iss-rental-cta\",\"backgroundColor\":\"eerie-black\",\"textColor\":\"vaporous-white\",\"layout\":{\"type\":\"constrained\"}} -->\n<section id=\"anfrage\" class=\"wp-block-group section iss-rental-cta has-vaporous-white-color has-eerie-black-background-color has-text-color has-background\"><!-- wp:group {\"className\":\"iss-container\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group iss-container\"><!-- wp:columns {\"verticalAlignment\":\"top\",\"className\":\"iss-rental-cta__grid\"} -->\n<div class=\"wp-block-columns are-vertically-aligned-top iss-rental-cta__grid\"><!-- wp:column {\"verticalAlignment\":\"top\",\"width\":\"62%\"} -->\n<div class=\"wp-block-column is-vertically-aligned-top\" style=\"flex-basis:62%\"><!-- wp:group {\"className\":\"iss-heading iss-heading\\u002d\\u002duncaged\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group iss-heading iss-heading--uncaged\"><!-- wp:paragraph {\"className\":\"iss-kicker iss-kicker\\u002d\\u002dlight\"} -->\n<p class=\"iss-kicker iss-kicker--light\">Anfrage</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"className\":\"iss-heading__title\",\"textColor\":\"vaporous-white\"} -->\n<h2 class=\"wp-block-heading iss-heading__title has-vaporous-white-color has-text-color\">Sie planen etwas Passendes für diesen Ort?</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"iss-heading__text has-vaporous-white-color has-text-color\"} -->\n<p class=\"iss-heading__text has-vaporous-white-color has-text-color\">Dann beschreiben Sie uns kurz Anlass, Wunschzeitraum und ungefähre Gruppengröße. Wir melden uns zurück, ob und wie sich Ihr Vorhaben im Industriesalon umsetzen lässt.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"verticalAlignment\":\"top\",\"width\":\"38%\"} -->\n<div class=\"wp-block-column is-vertically-aligned-top\" style=\"flex-basis:38%\"><!-- wp:group {\"className\":\"iss-rental-contact\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group iss-rental-contact\"><!-- wp:paragraph -->\n<p><strong>E-Mail</strong><br><a href=\"mailto:vermietung@industriesalon.de\">vermietung@industriesalon.de</a></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Telefon</strong><br><a href=\"tel:+49305309970\">030 5300 9970</a></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Sinnvoll in der Anfrage</strong><br>Anlass, Datum oder Zeitraum, Personenzahl, gewünschter Rahmen und besondere Anforderungen.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons -->\n<div class=\"wp-block-buttons\"><!-- wp:button -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\" href=\"mailto:vermietung@industriesalon.de?subject=Anfrage%20Salon-Vermietung\">Jetzt anfragen</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group --></section>\n<!-- /wp:group --></main>\n<!-- /wp:group -->','Salon Vermietung','','publish','closed','closed','','salon-vermietung','','','2026-06-04 12:41:51','2026-06-04 10:41:51','',0,'/?page_id=12606',0,'page','',0),
