(13359,1,'2026-05-02 20:13:06','2026-05-02 18:13:06','<!-- wp:html -->\n\n<style>\n.iss-video-spine__feature {\n  display: grid;\n  grid-template-columns: minmax(0,1.2fr) minmax(320px,0.8fr);\n  gap: clamp(2rem,5vw,5rem);\n  align-items: center;\n  margin-top: 3rem;\n}\n\n.iss-video-spine__feature img {\n  width: 100%;\n  aspect-ratio: 16/9;\n  object-fit: cover;\n}\n\n.iss-video-spine__intro-split {\n  display: grid;\n  grid-template-columns: minmax(0,1fr) minmax(320px,0.6fr);\n  gap: clamp(2rem,5vw,5rem);\n  align-items: start;\n}\n\n.iss-video-spine__two-col {\n  display: grid;\n  grid-template-columns: 1fr 1fr;\n  gap: 2rem;\n  margin-top: 2rem;\n}\n\n.iss-video-spine__chapter {\n  display: grid;\n  grid-template-columns: minmax(320px,0.8fr) minmax(0,1fr);\n  gap: clamp(2rem,5vw,5rem);\n  align-items: center;\n  margin-bottom: clamp(4rem,7vw,7rem);\n}\n\n.iss-video-spine__chapter img {\n  width: 100%;\n  aspect-ratio: 16/10;\n  object-fit: cover;\n}\n\n.iss-video-spine__chapter--reverse {\n  grid-template-columns: minmax(0,1fr) minmax(320px,0.8fr);\n}\n\n.iss-video-spine__register {\n  display: grid;\n  grid-template-columns: minmax(0,0.6fr) minmax(320px,1fr);\n  gap: clamp(2rem,5vw,5rem);\n}\n\n.iss-video-spine__list {\n  list-style: none;\n  margin: 0;\n  padding: 0;\n  border-top: 1px solid var(--iss-border);\n}\n\n.iss-video-spine__list li {\n  display: flex;\n  justify-content: space-between;\n  gap: 1rem;\n  padding: 0.8rem 0;\n  border-bottom: 1px solid var(--iss-border);\n  font-size: 0.95rem;\n}\n\n.iss-video-spine__list span {\n  color: rgba(30,30,30,0.6);\n}\n\n.iss-video-spine__access {\n  display: grid;\n  grid-template-columns: minmax(0,1fr) auto;\n  gap: 2rem;\n  align-items: end;\n  border-top: 1px solid var(--iss-border);\n  padding-top: 2rem;\n}\n\n@media (max-width: 900px) {\n  .iss-video-spine__feature,\n  .iss-video-spine__intro-split,\n  .iss-video-spine__two-col,\n  .iss-video-spine__chapter,\n  .iss-video-spine__chapter--reverse,\n  .iss-video-spine__register,\n  .iss-video-spine__access {\n    grid-template-columns: 1fr;\n  }\n}\n.iss-video-intro {\n  max-width: 58rem;\n}\n\n.iss-video-intro__title {\n  margin: 0 0 1rem;\n  max-width: 14ch;\n}\n\n.iss-video-intro__lead p {\n  margin: 0;\n  max-width: 42rem;\n  font-size: 1.05rem;\n  line-height: 1.6;\n  color: rgba(30,30,30,0.85);\n}\n\n.iss-video-intro__feature {\n  margin-top: 2rem;\n  padding-left: 1rem;\n  border-left: 3px solid var(--iss-red);\n  max-width: 40rem;\n}\n\n.iss-video-intro__feature-title {\n  margin: 0 0 0.5rem;\n  font-size: clamp(1.4rem, 1rem + 0.6vw, 1.9rem);\n  line-height: 1.15;\n}\n\n.iss-video-intro__feature-text {\n  margin: 0;\n  font-size: 0.98rem;\n  line-height: 1.5;\n  color: rgba(30,30,30,0.75);\n}\n</style>\n\n<section class=\"section section--plain iss-video-spine\">\n  <div class=\"iss-container\">\n\n    <div class=\"iss-heading iss-heading--uncaged\">\n      <p class=\"iss-kicker\">Zeitzeugen & Videos</p>\n      <h1 class=\"iss-heading__title\">Gedächtnis von Schöneweide.</h1>\n      <p class=\"iss-heading__text\">\n        Gespräche, Filme und Erinnerungen aus den Betrieben. Kein Videoarchiv im klassischen Sinn,\n        sondern Stimmen, die Arbeit, Technik und Alltag rekonstruieren.\n      </p>\n    </div>\n\n    <!-- FEATURE -->\n    <div class=\"iss-video-spine__feature\">\n      <figure class=\"iss-video-spine__feature-media\">\n        <img src=\"/wp-content/uploads/placeholder-video-feature.jpg\" alt=\"\">\n      </figure>\n      <div class=\"iss-video-spine__feature-text\">\n        <p class=\"iss-kicker\">Film</p>\n        <h2>Transformatorenwerk — Ein Ort verschwindet.</h2>\n        <p>\n          Dokumentarische Aufnahmen aus dem Werk und Gespräche mit ehemaligen Beschäftigten.\n          Produktionsabläufe, Umbrüche und der langsame Übergang nach 1990.\n        </p>\n        <p class=\"iss-video-spine__actions\">\n          <a class=\"iss-action-link\" href=\"#\">Video ansehen</a>\n        </p>\n      </div>\n    </div>\n\n  </div>\n</section>\n<section class=\"section section--plain\">\n  <div class=\"iss-container\">\n\n    <div class=\"iss-video-intro\">\n      <p class=\"iss-kicker\">Zeitzeugen &amp; Videos</p>\n\n      <h1 class=\"iss-video-intro__title\">\n        Gedächtnis von Schöneweide.\n      </h1>\n\n      <div class=\"iss-video-intro__lead\">\n        <p>\n          Gespräche, Filme und Erinnerungen aus den Betrieben.\n          Kein Videoarchiv im klassischen Sinn, sondern Stimmen,\n          die Arbeit, Technik und Alltag rekonstruieren.\n        </p>\n      </div>\n\n      <div class=\"iss-video-intro__feature\">\n        <p class=\"iss-kicker iss-kicker--compact\">Film</p>\n\n        <h2 class=\"iss-video-intro__feature-title\">\n          Transformatorenwerk — Ein Ort verschwindet.\n        </h2>\n\n        <p class=\"iss-video-intro__feature-text\">\n          Dokumentarische Aufnahmen aus dem Werk und Gespräche mit ehemaligen Beschäftigten.\n          Produktionsabläufe, Umbrüche und der langsame Übergang nach 1990.\n        </p>\n      </div>\n\n    </div>\n\n  </div>\n</section>\n<section class=\"section section--tint iss-video-spine\">\n  <div class=\"iss-container\">\n\n    <!-- RIGHT HEADING / LEFT TEXT -->\n    <div class=\"iss-video-spine__intro-split\">\n      <div class=\"iss-video-spine__intro-text\">\n        <p>\n          Die Interviews entstehen oft vor Ort: in Werkhallen, auf Brachen,\n          an verbliebenen Maschinen. Erinnerung ist dabei nicht nur Erzählung,\n          sondern an Räume und Dinge gebunden.\n        </p>\n        <p>\n          Die Filme verbinden persönliche Perspektiven mit technischer Praxis:\n          Arbeitsabläufe, Improvisationen, Routinen — und das Wissen, das nicht\n          in Dokumenten steht.\n        </p>\n      </div>\n      <div class=\"iss-video-spine__intro-heading\">\n        <p class=\"iss-kicker\">Kontext</p>\n        <h2>Erinnerung ist ortsgebunden.</h2>\n      </div>\n    </div>\n\n    <!-- TWO COLUMN TEXT -->\n    <div class=\"iss-video-spine__two-col\">\n      <div>\n        <h3>Produktion</h3>\n        <p>\n          Wie wurde gearbeitet? Welche Materialien, welche Maschinen, welche\n          Entscheidungen bestimmten den Alltag?\n        </p>\n      </div>\n      <div>\n        <h3>Übergänge</h3>\n        <p>\n          1989/90 und danach: Brüche, Stillstand, Anpassung — und neue Formen\n          der Nutzung industrieller Räume.\n        </p>\n      </div>\n    </div>\n\n  </div>\n</section>\n\n<section class=\"section section--plain iss-video-spine\">\n  <div class=\"iss-container\">\n\n    <!-- CHAPTER ROWS -->\n    <div class=\"iss-video-spine__chapter\">\n      <figure>\n        <img src=\"/wp-content/uploads/placeholder-wf.jpg\" alt=\"\">\n      </figure>\n      <div>\n        <p class=\"iss-kicker iss-kicker--compact\">WF</p>\n        <h2>Werk für Fernsehelektronik</h2>\n        <p>Arbeit, Forschung und Umbruch in einem der größten Elektronikbetriebe der DDR.</p>\n        <a class=\"iss-action-link\" href=\"#\">Filme ansehen</a>\n      </div>\n    </div>\n\n    <div class=\"iss-video-spine__chapter iss-video-spine__chapter--reverse\">\n      <figure>\n        <img src=\"/wp-content/uploads/placeholder-kwo.jpg\" alt=\"\">\n      </figure>\n      <div>\n        <p class=\"iss-kicker iss-kicker--compact\">KWO</p>\n        <h2>Kabelwerk Oberspree</h2>\n        <p>Material, Produktion und internationale Verflechtungen.</p>\n        <a class=\"iss-action-link\" href=\"#\">Filme ansehen</a>\n      </div>\n    </div>\n\n    <div class=\"iss-video-spine__chapter\">\n      <figure>\n        <img src=\"/wp-content/uploads/placeholder-tro.jpg\" alt=\"\">\n      </figure>\n      <div>\n        <p class=\"iss-kicker iss-kicker--compact\">TRO</p>\n        <h2>Transformatorenwerk</h2>\n        <p>Großbetrieb, Stilllegung und neue Nutzungen.</p>\n        <a class=\"iss-action-link\" href=\"#\">Filme ansehen</a>\n      </div>\n    </div>\n\n  </div>\n</section>\n\n<section class=\"section section--tint iss-video-spine\">\n  <div class=\"iss-container\">\n\n    <!-- ZEITZEUGEN REGISTER -->\n    <div class=\"iss-video-spine__register\">\n      <div>\n        <p class=\"iss-kicker\">Zeitzeugen</p>\n        <h2>Wer spricht.</h2>\n      </div>\n\n      <ul class=\"iss-video-spine__list\">\n        <li><strong>Joachim Zamzow</strong> <span>WF — Werkzeugmacher — 1957–1992</span></li>\n        <li><strong>Gerhard Preußler</strong> <span>WF/Samsung — Ingenieur — 1965–2005</span></li>\n        <li><strong>Dieter Scholz</strong> <span>TRO/OBS — Eisenbahner — 1969–1999</span></li>\n        <li><strong>Weitere Interviews</strong> <span>laufend ergänzt</span></li>\n      </ul>\n    </div>\n\n  </div>\n</section>\n\n<section class=\"section section--plain iss-video-spine\">\n  <div class=\"iss-container\">\n\n    <!-- ACCESS / BRIDGE -->\n    <div class=\"iss-video-spine__access\">\n      <div>\n        <p class=\"iss-kicker\">Verbindung</p>\n        <h2>Von Stimmen zu Orten.</h2>\n        <p>\n          Die Filme sind Teil der Sammlung. In Führungen und Ausstellungen werden sie mit\n          Objekten, Orten und aktuellen Fragen verknüpft.\n        </p>\n      </div>\n\n      <div class=\"iss-video-spine__actions\">\n        <a class=\"iss-action-link\" href=\"/fuehrungen/\">Führungen</a>\n        <a class=\"iss-action-link\" href=\"/ausstellungen/\">Ausstellungen</a>\n      </div>\n    </div>\n\n  </div>\n</section>\n<!-- /wp:html -->','videos','','publish','closed','closed','','videos','','','2026-06-03 07:48:30','2026-06-03 05:48:30','',0,'/?page_id=13359',0,'page','',0),
(13368,0,'2026-05-03 09:24:31','2026-05-03 07:24:31','<!-- wp:paragraph -->\n<p><strong>[00:05]</strong> Oberschöneweide war teil gewählten Elektropolis von hier aus begann die weltweite elektrifizierung die industrielandschaft an der spree stehen für die großen gründerjahre es begann mit den netzwerken ab 1901 wurden ihr werkzeug maschinen in massenfertigung gebaut gebaut im ersten weltkrieg wuchs die produktion so stark an dass die hallen zu klein wurden nun übernahmen die allgemeine elektrizitätsgesellschaft AEG ihre schutz marke war die göttin des lichts unter der leitung von emiraten aufwuchs aus der produktion von glühlampen ab 1893 ein weltweit führender Elektrokonzern 1921 nahm das kanzler motorenwerk Oberschöneweide das trio den betrieb auf die aig beauftragte führende architekten für den weiteren ausbau der riesigen industrieanlagen inTRO wurden groß transformatoren für kraftwerke in der ganzen welt gebaut auch der weltweit größte 1 phasen transformator gelangte hier zur</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>[01:01]</strong> serienreife die transformatoren sind für eine netzspannung von 132.000 volt und für eine übertragungsleistung von 100 mv berechnet TROtz dieser großen leistungen und der hohen spannung dürfen die ausmaße der transformatoren das eisenbahn profil nicht überschreiten eine aufgabe die vom Elektroingenieur technologen und konstrukteur gemeinsam gelöst werden muss die transformatoren wurden aufzügen aus den hallen transportiert transportiert sie waren so groß dass sie zwischen den achsen der eisenbahnwaggons gehängt werden mussten transformatoren mussten auch wetterfest sein ein spannungs generator auf dem dach generierte blitze die ein starkes gewitter simulierten die rollen ladungen nutzen physiker auch erstmals zur</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>[02:02]</strong> erzeugung von röntgenstrahlen im zweiten weltkrieg wurde dann auf rüstungsproduktion umgestellt größter kunde wurde die wehrmacht im tor waren etwa 1500 zwangsarbeiter und zwangsarbeiterinnen beschäftigt untergebracht waren sie in bewachten lagern lagern [Musik] nach ende des krieges wurden trümmer beseitigt und straßenbahn repariert die AEG wurde enteignet und die sowjetunion demontierte ganze hallen dann wurden im tor wieder anlagen für kraftwerke gebaut hochbetrieb in den montagehallen des transformatoren werkes karl liebknecht Oberschöneweide kampfziel der werktätigen im gros trafo bau ist eine kontinuierliche planerfüllung für die energiewirtschaft der DDR und den export die arbeitsproduktivität soll um ein prozent über den tag hinaus gesteigert</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>[03:03]</strong> werden der schwerpunkt neben der rein zahlenmäßigen erfüllung der aufgaben ist auf jeden fall die qualität die stetige qualität in unserem grund transformatoren damit die volkswirtschaft der DDR kontinuierlich jeden tag mit energie versorgt werden kann kann als die mauer fiel geriet asTRO in schweres wasser die Treuhand teilte das unternehmen kündigte 3000 mitarbeitern beseitigte schwerster umweltschäden und suchte käufer 1992 übernahm die aig den transformatoren bau und verhör war stolz darauf AEG berlin weltweit ein begriff wenn es um große transformatoren gehen leistungen von 300 400 bis 800 m vor</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>[04:06]</strong> diego hat mit ihren kernprodukten transformatoren und geräte 75 jahre lang die industriegeschichte dieser branche maßgeblich beeinflusst die mitarbeiter haben wesentlich dazu beigetragen das tor als synonym für eines der bedeutendsten transformatoren werke deutschland stehe ich und der standort Oberschöneweide weit über deutschland hinaus bekannt wurde [Musik] [Musik] drei monate später wurde das werk geschlossen proteste halfen nichts der markt in osteuropa eingebrochen das management hatte fehler gemacht die AEG entschied sich für ein zweigwerk in westdeutschland die zeit der industrie war vorbei Elektropolis geschichte die leeren hallen wurden weiterverkauft wechselnde investoren versuchten ihr glück mit großevents und zwischennutzungen das abfahrten lohnte sich der preis stieg an 2009/10 kaufte ein vom das</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>[05:08]</strong> denkmalgeschützte areal nun soll hier ein neues quartier entstehen eine studentenstadt mit wohnungen büros und einzelhandel einzelhandel es bleibt zu hoffen dass die ambitionierten pläne den geist des ortes bewahren in Oberschöneweide soll das erbe der berliner Elektropolis leben als moderne stadt mit starken wurzeln und einer spannenden zukunft o o [Musik]</p>\n<!-- /wp:paragraph -->','Transformatorenwerk Oberschöneweide (Rathenauhallen)','Kurzgeschichte über das Transformatorenwerk Oberschöneweide (Rathenauhallen).','publish','closed','closed','','transformatorenwerk-oberschoneweide-rathenauhallen','','','2026-06-03 06:17:31','2026-06-03 04:17:31','',0,'/?post_type=video&#038;p=13368',0,'video','',0),
(13369,0,'2026-05-03 09:24:31','2026-05-03 07:24:31','<!-- wp:paragraph -->\n<p><strong>[00:03]</strong> luxuslimousinen und kleinwagen die automobile aus Schöneweide hatten einen exzellenten ruf im ersten weltkrieg ließ die AEG diese automobilfabrik bauen ein monument des modernen industriebaus des zwanzigsten jahrhunderts für die kraftvolle architektur steht Peter Behrens ab 1907 künstlerischer beirat der AEG und damals der bedeutendste architekt der deutschen großindustrie im zentrum steht der monumentale lichthof eingang für direktoren wie für arbeiter die aufwändige ausgestaltung kündete von der leistungskraft der nationalen automobilgesellschaft einer tochter der rag schon seit dem ende des neunzehnten jahrhunderts produzierte die Elektromobile in schöner weiter dazu kamen sportwagen die viele große autorennen gewannen auch die lastwagen der energie galten als leistungsstark und zuverlässig genauso wie die stadt omnibusse der ovale schüler das berliner straßenbild beherrschten</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>[01:03]</strong> doch 1934 war es vorbei die teuren luxuswagen waren nicht mehr konkurrenzfähig die automobilproduktion wurde beendet nun zog ein betriebsteil von telefunken in das gebäude ein zu dessen produktionspalette gehörte die entwicklung von fernsehtechnik und kriegswichtige elektronik auf dem toom bei eine flakstellung aber wurden bombardiert 1945 übernahmen die sowjets die röhre fabrik und bauten sie aus dieser aufnahmen zeigen den bau von bildröhren für den ersten fernsehempfänger der sowjetunion den leningrad t2 täglich musste eine anzahl kompletter höheren sätze fertiggestellt werden erst wenn das tages soll erfüllt war öffneten sich die faktoren 1952 wurde der sowjetische betrieb als volkseigentum an die DDR übergeben was uns fehlt sind arbeitskräfte brauchen sie spezial oder fachkräfte</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>[02:03]</strong> nicht nur auch ungelernte jugendliche und besonders unsere noch nicht berufstätigen hausfrauen würden wir uns interessante und lohnende arbeit finden tja unsere hausfrauen manche von ihnen verbinden in gedanken fabrikarbeit immer noch wie früher mit körperlich schwer schmutzig einförmig dabei wissen viele gar nicht wie es in einem so modernen werk wie in unseren aussieht [Musik] [Musik] [Applaus] und ihren das ist demontagearbeiten fast ausschließlich frauen unter solchen bedingungen muss die arbeiter freude machen unsere frauen hier fühlen sich alle wie zu hause und ihre arbeit ist wirklich tiptop das werk für Fernsehelektronik WF entwickelte sich zum größten berg Ost-Berlins eine</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>[03:04]</strong> art high tech tempel DDR neben Farbbildröhren und sendeanlagen wurden auch begehrte elektronikartikel für den privaten konsum hergestellt als die mauer fiel kam für die meisten betriebsteile das aus auf dem weltmarkt konnte dass wir es nicht mithalten elektronik wurde im westen günstiger produziert die märkte wachen abgeschottet anlagen ausstattung und erfahrung landeten auf dem müll die Treuhand macht aus dem WF ein gmbh und reduzierte die belegschaft von 9000 auf 1400 mit unterstützung von fördermitteln kaufte Samsung 1993 das gelände und übernahm das Farbbildröhrenwerk um auf dem europäischen markt fuß zu fassen die 800 beschäftigten waren bereit sich den neuen anforderungen zu stellen auch</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>[04:06]</strong> wenn die löhne unter das niveau lagen bis 2005 holten etwa 40 millionen bildröhren von den bändern dann war das zeitalter der röhrenfernseher beendet proteste hungerstreiks und politiker reden konnten auch den letzten großen arbeitgeber in Schöneweide nicht halten 2009 verkaufte Samsung das große werksgelände an einen investor der sich als spekulant erwies er ließ die hallen weitgehend leer stehen und wartete ab die nachfrage nach seinem filetstück an der spree mit dem markanten Peter Behrens bau stieg auch ohne sein zutun 2009 10 wurde mit großem gewinn weiterverkauft an die deutsche entwicklungsachse lände zu einem urbanen quartier mit büros und service-einrichtungen werden der denkmalgeschützte Peter Behrens bau wird sich gegen die neuen hochhäuser behaupten müssen</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>[05:12]</strong> in Schöneweide zieht die zukunft ein unverwechselbar blätter standort durch seine große industriegeschichte o o [Musik]</p>\n<!-- /wp:paragraph -->','Werk für Fernsehelektronik','Video zur Geschichte des Werk für Fernsehelektronik.','publish','closed','closed','','werk-fur-fernsehelektronik','','','2026-06-03 06:14:40','2026-06-03 04:14:40','',0,'/?post_type=video&#038;p=13369',0,'video','',0),
(13371,0,'2026-05-03 09:24:31','2026-05-03 07:24:31','<!-- wp:paragraph -->\n<p><strong>[00:00]</strong> [Musik]</p>\n<!-- /wp:paragraph -->','Die Kabeltrommelfabrik vom KWO','Der Bau der Kabeltrommeln für das Kabelwerk Oberspree (KWO) befand sich bis 1990 am gegenüberliegenden Spreeufer in der Nähe vom S-Bahnhof Schöneweide, direkt an der Spree. Trommelbau war harte körperliche Arbeit, die fertigen Trommeln wurden per Schiff transportiert.','publish','closed','closed','','die-kabeltrommelfabrik-vom-kwo','','','2026-06-03 06:05:48','2026-06-03 04:05:48','',0,'/?post_type=video&#038;p=13371',0,'video','',0),
(13372,0,'2026-05-03 09:24:31','2026-05-03 07:24:31','<!-- wp:paragraph -->\n<p><strong>[01:12]</strong> Farbbild rührenwerk solange das hier sich um den Teil unter Toshiba Lizenz in der DDR ja handelt hat da wurden zwei Typen produziert drei Typen Entschuldigung 3 einem der damaliges Werk war ja mehr oder weniger für den inlandbedarf da haben wir 600.000 Bilder in etwa im Jahr gemacht nur kleinere Teile sind in den Export gegangen aber das war der Anfang und auch mit allen vier Werk DDR und hier dieser Teil der nachher bebaut wurde durch den farbbetreuenweg ist dann die Bandbreite entstanden als Verbindung zum anderen Gebäudeteil hier wurde also der Grundstein gelegt und wie wir auch schon sehen hier also verschiedene Parteitage ich sehe hier an der Seite unseren Dank gilt dir Partei also unter diesen Slogan wurden hier die großen Ereignisse</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>[02:14]</strong> in der ganzen Republik verkauft die also die hier zum Beispiel so Parade stehen müssen oder so weil ja das sind ausgesuchte Leute gewesen da konnte man ja irgendwann mal hingehen und sagen oh guck mal zu wird was da los ist abgesperrt und man darf nicht wahrhaben das die Beschäftigten hier die hier gearbeitet haben natürlich auch möchte ich stolz waren weil Farbbildröhren machen das ist ja schon noch eine größere Kunst und man hätte ja wenn man ihr wollt hätte das auch in Leipzig bauen können aber natürlich noch unterwegs schon mit dem westlichen Ausland und der neue Japan was zu tun oder wir waren schon stolz da gibt&#039;s keine Frage diese Teile wurden unter anderem hier macht Einzelteile dafür nicht so komplett wie es jetzt hier ist aber das die Strahlsystem Fertigung früher die wir hier im eigenen Hause betrieben hatten übrigens auch sage ich nicht ohne</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>[03:15]</strong> Stolz unsere Karton ein wichtiges Herzstück eines jeden strahlsystems auch in Schwarz-Weiß bildet die Kathode und am Ende macht die Kathode die Lebensdauer der Welt Röhre aus und unsere Karton die wir hier gemacht haben an Standort die waren außerordentlich guter Qualität weil sie eine sehr sehr große Lebensdauer hatten für die schweißsteuereinheit und hier also die punktschweißzange und dann konnte man hier unten mit dem Fuß rauf treten auf den Auslöser und hat dann hier die Metallteile geschweißt hier saßen vorn nämlich Darm weil das eine relativ leichte Arbeit war aber TROtzdem sehr genau sehen musste und ja hier haben wir sind wir schon in der nicht Etage unten wir sehen hier also Schirm</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>[04:17]</strong> Teil angesaugt auf einer Rotationsmaschine hier wird der Bildschirm mit Leuchtstoff beschichtet auf die später wenn alle in Ordnung ist verschweißt zu werden mit dem Trichter für einen lastteil ung zu sehen die Phosphor Schichten die drei verschieden die aufgebracht wurden auf dieser vorherigen rotary-maschine die sind lichtempfindlich eine lichtempfindliche Anteil ist darin so dass also in den Räumen jetzt mit UV-Licht von unten die Leuchtstoffe die eingebracht wurden belichtet werden konnten eine Notwendigkeit um Rot Grün und Blau nicht zu mischen auf dem Bildschirm sondern in Mikrometer Mikrometer Feinstrukturen nebeneinander abzulegen</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>[05:19]</strong> und das also eine außerordentlich komplexe Fertigung wir sehen hier das gelblich ist im ganzen Raum war gelblich andere Licht hätte nicht genommen werden dürfen sonst wären diese Teile wie damals in der Fotoindustrie vorbelichtet gewesen ja hier sehen wir also schon die Teile der Pumpe ist ja Ausgang hier und Eingang wir sehen hier jeder einzelne Pumpstation die sich langsam in einem Takt von etwa zwei Stunden durch den Ofen der hier also außerordentlich hohe Temperaturen erzeugt hier fahren werden und diese Körbe die man hier sieht die sind eigentlich nur Schutz für die benachbarten weil hin und wieder passiert ist durch Beschädigung einer Glasfläche während des Prozesses das hat</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>[06:20]</strong> beim Pumpen ein riesen Knall gibt und ein Inklusion stattfindet und bei der Inklusion fallen alle Splitter nach innen weil ja in evakuiert ist aber wenn sie auseinander treffen fliegen sie wieder raus überall hin und wenn diese Splitter die Nachbarn will drin treffen dann gibt es sogenannte Ketten Inklusion so dass man später das war gar nicht von Anfang an auf die Idee kam Mensch wir Hausen jedes einzelne stell ein wenn die hier knallt dann bleibt die wenigsten leben</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>[07:20]</strong> ja hier ist also schon fast das Ende der Bildung das sei sogenannte jam-bereich also der Bereich bei denen die bilDDRehen justiert wurden zur damaligen Zeit das ist ja hier alles noch Toshiba Lizenz sehen wir das sind einzelne Stände waren und die bildrinnen also von den Kollegen hier per Hand eingesetzt werden mussten und hier wird also die sogenannte uplinkeinheit mit der Bildröhre justiert und denn fest fixiert so dass er sich nicht mehr löst und als Produkten als Bauelement wildröhre verkauft</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>[08:23]</strong> ich sollte man etwas noch zum Schluss sagen für diesen Standort der betrieblich ist betrieblich betrüblich ist so sagt ja also nachdem nachdem die DDR zusammengebrochen haben ist nach der Wiedervereinigung sagte ja schon sind viele chefsfelder die hier an diesem Standort beherbergt waren zusammengebrochen weil sie einfach nicht weltmarktfähig waren und leider bereutet für alle die die hier also Jahrzehnte erarbeitet haben dass sie ihren Arbeitsplatz verlieren mussten aber die Zeiten sind leider vorbei das war auf Lebenszeiten so wie ich über 40 Jahren an einem Ort</p>\n<!-- /wp:paragraph -->','Das Farbbildröhrenwerk der DDR, Teil vom Werk für Fernsehelektronik (WF)','Das moderne Fabrbbildröhrenwerk gehörte zum Werk für Fernsehelektronik, dem – mit etwa 9.000 Mitarbeitern- größten Werk Ostberlins. Das moderne Werk wurde Ende der 80iger Jahre von der DDR komplett von Toshiba gekauft und mit japanischer Unterstützung in Schöneweide aufgebaut. Der Abteilungsleiter Gerhard Preußler erklärt die Technologien.','publish','closed','closed','','das-farbbildrohrenwerk-der-ddr-teil-vom-werk-fur-fernsehelektronik-wf','','','2026-06-03 06:13:46','2026-06-03 04:13:46','',0,'/?post_type=video&#038;p=13372',0,'video','',0),
(13373,0,'2026-05-03 09:24:31','2026-05-03 07:24:31','<!-- wp:paragraph -->\n<p><strong>[00:00]</strong> [Musik] Ich habe damit nichts zu tun. Mir ist das vollkommen wurscht, würde ich gerne sagen. Ich verstehe den Denkmalschutz so nicht. Man kann nicht alles unter Denkmalschutz stellen.</p>\n<!-- /wp:paragraph -->','Abriss der denkmalgeschützten Fernmeldekabelfabrik - Architekt Ernst Ziesel - im Jahr 2007','Die Fernmeldekabelfabrik, erbaut 1927-28, stand auf dem heutigen Campus der Hochschule für Technik und Wirtschaft Berlin(HTW). Mit dem Umbau des östlichen Teils vom ehemaligen Kabelwerk (KWO) zum neuen Campus der Hochschule, wurde die leerstehende Fabrik 2007 abgerissen, obwohl sie seit 1977 unter Denkmalschutz stand. Sie galt als eine der ersten Stockwerksfabriken in Stahlskelettbauweise. Der radiklale Funktionalismus des Architekten Ernst Ziesel war Vorreiter des Neuen Bauens – eine Bewegung, die sich ganz der Sachlichkeit und Ökonomie verschrieben hatte und die die ideelle Grundlage der Bauhaus-Schule bildete.','publish','closed','closed','','abriss-der-denkmalgeschutzten-fernmeldekabelfabrik-architekt-ernst-ziesel-im-jahr-2007','','','2026-06-03 06:05:48','2026-06-03 04:05:48','',0,'/?post_type=video&#038;p=13373',0,'video','',0),
(13374,0,'2026-05-03 09:24:31','2026-05-03 07:24:31','<!-- wp:paragraph -->\n<p><strong>[00:00]</strong> [Musik] Kurze Verständigung im Führerstand; einzelne Zurufe sind im Ton nur bruchstückhaft verständlich.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>[01:38]</strong> [Fahrgeräusche] Einzelne Anweisungen und kurze Rückfragen im Führerstand.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>[02:58]</strong> [Fahrgeräusche] Gesprächsfetzen zur Fahrt; der genaue Wortlaut ist nicht zuverlässig verständlich.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>[04:52]</strong> [Fahrgeräusche] Kurze Zurufe während der Fahrt.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>[06:10]</strong> [Fahrgeräusche] Kurze Verabschiedung im Führerstand.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>[07:18]</strong> [Fahrgeräusche] Einzelnes bestätigendes Zurufen.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>[08:35]</strong> [Fahrgeräusche] Weitere kurze, nur teilweise verständliche Bemerkungen.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>[09:56]</strong> [Musik]</p>\n<!-- /wp:paragraph -->','Der Bulle - Fahrt im Führerstand der Industriebahn durch Oberschöneweide','Führerstandsmitfahrt mit der Bullenbahn E-Lok 25001 der rumänischen Lokfabrik FAUR aus Bukarest durch die Wilhelminenhofstraße in Schöneweide im Jahre 1993 – eine Erinnerung an alte Zeiten. – Zusammen mit der wachsenden Industrie wurde auch die Industriebahn ausgebaut. Am 1. August 1901 verkehrte die erste elektrische Lokomotive in Schöneweide. 1957 war die Bahn rund 13 Kilometer lang und bediente 30 Werksanschlüsse.','publish','closed','closed','','der-bulle-fahrt-im-fuhrerstand-der-industriebahn-durch-oberschoneweide','','','2026-06-03 06:05:48','2026-06-03 04:05:48','',0,'/?post_type=video&#038;p=13374',0,'video','',0),
(13376,0,'2026-05-03 09:24:31','2026-05-03 07:24:31','<!-- wp:paragraph -->\n<p><strong>[00:07]</strong> ich habe 1948 in einem kleinen betrieb in bon jovi gelernte werkzeugmacher und bin dann in dem betrieb neuen jahres nehmen und von dort habe ich dann hier wechseln wobei ich dazu sagen muss bayern sozusagen als sie dort ausgeschieden bin ich bin mal sinnieren und darüber zum frühstück bei einer kündigung gestrichen es erfolgen dann spontan und papier dazu jetzt auf arbeitssuche und habt jene von sieben deshalb 750 zuhause von ich bin ja sämtliche betriebe ab gelaufen und habe gesagt so jetzt noch einen betrieb wir haben ich glaube damals die entscheidung eine wohn jetzt noch einen betrieb WF unter nächsten mal fragen und so bin ich hier eine kommt die unter betrunkenen sondern sogar anmeldung und und leute die so nutz und stolz büro und die haben mich denn je hoch schickt und</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>[01:07]</strong> die ach so der unten sagte dan also risiken Strom ist eine stelle frei bringen sie mal da hoch war ja damals alles noch bewegt da hoch wären und der sagt zu mir gesucht sagten es sei ein werkzeugmacher und da sagte aber sie sind sie haben ja schon in gruppe 8 die bezahlen bezahlen er wollte mich nicht in den hat er aber unser werkzeugbau unten ich sage ja der suche geht weiter ach wissen sie ich bringe sie mal runter ist er selber mit runtergekommen jeder abteilungsleiter hat michael zu der kollegin schilling gebracht und der hat dann gesagt ja also wir suchen ja kinder wachsen wir sind ja endlich voll und dann hat er den obermeister hürther der hofft dort auf den bildern ist geholt und den kannte ich kannten nicht so alt aber meine frau die hat mit dem in einem haus gewohnt ja die haben in dem haus zusammen über die die tochter von dem zucker begleiter waren im konter</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>[02:12]</strong> haben wir uns dann so reinigt und da sagte er zu mir also wenn ich sie ja einsteller dann nur als werkzeugmacher für die instandhaltung der werkzeug und etwa zehn jahre mit der lehre zusammen neuen jahre leistungslohn er arbeitet ja schon so wartet war eine recht koller hetze was mir eigentlich bei der jude der werkzeuge die wir fertig haben jugendliche legen hat egal sagt also dann da braucht die kinder abrechnung machen monier christenfest nun das stundenlohn der war je höher wie dort weil das war schwer maschinenbaubetrieb und wir hatten dort ein machine und daher ab 233 mal kundenparkplätze die spitze erwartet wesentlich höher ist die gruppe wie ich hier angefahren WFs like soll ich mal bei der verabschiedung dass gruppen laie dass dort der mit dem kreuz mit dem</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>[03:13]</strong> werkzeug maradona weiter die waren ja alle sein möchte ich sagen seit 45 hier dabei werkzeugbau in der schraubstock ein schraubstock und dann wohnen hier hier stehen zum beispiel beim schnitt leicht sauer und stanzwerkzeuge vermute mal für die iem einer höheren produktion juliane und funkel baut ihr und das sind die werkzeuge die je gebaut wurden dabei unterteilt dieser ernsten ganz hinten vorrichtungsbau wir haben so vorrichtungen für die montage und somit gebaut dazwischen gab es die neubau den schnitt bauen die haben die schnitte und stanzwerkzeuge gemacht und hier hinten hatten wir dann eine ecke wird war so unser verein für die instandhaltung dieser werkzeuge die mussten ja erwartet</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>[04:14]</strong> werden werden das war eine unheimliche zahl der hat produktion der unheimlich hoch war und ja so viele röhren gebaut ja die haben ja radio an bord für siemens sei unbeschriftet an siemens liefern und wurden denn bei siemens erst beschriftet mit sieben zu holen so werkzeug kaputt war wendet nur zum schleifen und zu schaffen war denn auch diese teile dieser aus stanzteile die mussten ja grad frei sein und dann muss man ab und zu auch geschafft werden und dann wendet normal war und nichts kaputt war wartet alle rollen war eigentlich relativ einfach die werkzeuge wohnen nachher ist komplizierter als in diese neigen in diesen werkzeugen die einzelnen schritte so wie sie hier zu sehen sind da sind ja denn erst ausschnitte und dann kommt ein prozess zu wurde die bohrung wird da werden einzelne teile among und zum schluss ganz heißer tanz werden sie</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>[05:14]</strong> trennt aus ihrem eigenen körper sodass nach die abhalten da wo unsere dann nachher ein bisschen komplizierter immer noch die röhren teile der forschung und in den werkzeugen auf ein bisschen komplizierter darf man da nun extra geschult wurde getränke sorgen wir haben ja sachen gebaut die wir die wir vorher gebaut haben mit unseren ideen und die konstruktion hatte dann nur verfeinert nach oliver schon eine recht interessante sache hat mir spaß gemacht die bastelei macht mir heute noch schwach bin ich hier gelandet und den rehen waren alle nett und rupert einwandfreie konnte er in berlin</p>\n<!-- /wp:paragraph -->','Zeitzeuge Joachim Zamzow','Zeitzeuge Joachim Zamzow, WF, Werkzeugmacher, 1957 – 1992','publish','closed','closed','','zeitzeuge-joachim-zamzow','','','2026-06-03 06:14:41','2026-06-03 04:14:41','',0,'/?post_type=video&#038;p=13376',0,'video','',0),
(13378,0,'2026-05-03 09:24:31','2026-05-03 07:24:31','<!-- wp:paragraph -->\n<p><strong>[00:08]</strong> mein name ist stolz ich habe von 1969 bis zum schluss hier gearbeitet insgesamt 30 jahre 20 in der DDR und zehn in der brd ich war hier als anschlussbahn leiter tätig in der abteilung transport und versand nicht ohne grund stehen wir hier auf der großen drehscheiben eisenbahnwaggons die von der behala den betrieb zugestellt wurden kam hier auf dem hauptpreis an wurden dann von uns mit eigener technik eigener lokomotive spielanlage und so weiter in den betrieb geholt hier abgedreht auf dem hof oder in die halle gestellt von anschlussbahnen leid aber verantwortlich wie die pflege für die wartung der anlagen hier wir hatten insgesamt sechs drehscheiben mehrere hand weiten signale prellbock eigene eisenbahn waren alte ausgediente von der</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>[01:08]</strong> reichsbahn die wir für unseren innerbetrieblichen transport genutzt haben im betrieb arbeiteten circa 5.000 in unserer abteilung das ist das direktorat einkauf und versand gewesen von 300 ungefähr und von diesen 300 waren zehn ausgebildete eisenbahn engagiere rote streifen das war die kühlanlage gewinn von wolfsburg industrie warnung gemacht habe habe unterwegs ca 20 anlegern die von der behala mithalten bahnwaggons verdient worden sondern von anfang an transformatoren hier gebaut die wollen zuallererst in der innenstadt gebäude in der brunnenstraße das war aber zu sehr in stadt zu eng hier hat man einen großen raum konnten sie ausbreiten und da wurden</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>[02:08]</strong> transformator hier wollen alle möglichen transport ohren für die dörfer diese kleinen klingelt ramos ist riesengroß ich waren so groß wie ein haus und wogen 200 die wurden hier gebaut und transportieren und weil das einzige große maschinen war konnte man die auf der straße nicht transportieren zb und musste hat den schienenweg gewählt statt wurden die straßenbahn personenverkehr mit pferden gezogen und hier die transport ohren auf ihren schweren wagen mit einem bullen deswegen sagt hier alles was sie es vorsicht der polizei wenn eisenbahn zustellung war die behala ankam hat er die 20 30 40 wagen manchmal eisenbahn waren und die allerletzten wenn sie hier war gehörten wann tue das waren 4 5 am tag der trauer an juli verloren verloren wir wurden hier abgestellt und dann mit</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>[03:08]</strong> unsere eigene technik hochgezogen und ein teil ging in die halle da wurde verladen alles was fertig war auf dem hof wenn kohle kam zum beispiel liebe wurde hier abgedreht und dann weitergefahren zum coolen der die rangierung mussten rund um die uhr arbeiten an eintragen in drei schichten und wir haben noch mal gearbeitet die rangieren hatten hier dieser hübsche bauer weinanbau und da saßen dinge zu war meistens eine schick finden muss weil die behala fünfmal am tag zugestellt hat um 13 uhr und 17 uhr um 21 uhr und 24 uhr die eisenbahn frage nicht jetzt ist ein wagen tag kann man stehen lassen die wollten dass die wagen</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>[04:09]</strong> rotieren und viel geld bringen aus dem grunde musste rund um die uhr gearbeitet be- und entladen werden wenn ein waren hier stehen blieb und nicht konnte war keine leute da waren oder was weiß ich warum dann muss die strafe zahlen an die eisenbahn interessant ist diese nebenstraße fahrgast war der innerbetriebliche transport untergebracht noch früher die pferdeställe es ist noch keine spielanlage und noch keinen elektrischen anlagen war für die eisenbahnwagen wurden wurden die waggons mit pferden gezogen und ihr waren die pferdeställe die wahren angebaut wo die hellen stellen sind da waren anbau pferdeställe und später in der kriegszeit worden dort kriegsgefangene untergebracht die hier arbeiten müssten russische kriegsgefangene ich habe vor zuguckt habe aber nicht mal gefunden konnte man noch die bullische</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>[05:10]</strong> schrift lesen achtung du darfst nicht oder verbot oder so was geschehen muss noch frei sein dass maschinen und gleichzeitig auch für die elterliche straße und alle waren die produziert wurden die wurden hier am rand abgestellt irgendwann wurden so abgerufen wurden hier eine kartbahn da sieht man noch die einzelnen feiler sonntag raten waren nicht diese feier hier wir prüfen genau dasselbe tat muss abgebaut werden die geräte abgefragt worden da wurden zu verladen auf lkw oder auf die eisenbahn winter war das alles hier und dann mit einem schweren eisenbahn herzig tonnen und mehr hier drüber zu fahren das geht entweder der eisenbahn forderung and leiste oder springt gar nicht da mussten den aufbau der engagieren engagieren diese willen immer frei gewählt werden schwerstarbeit auf gleise gleise gleise</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>[06:25]</strong> hier war waren abgestellt fertige ware die verladen werden sollte hier wurde verpackt und hier ungefähr war das meiste wird angehoben hier wurden dann auch diese riesengroßen trafos verladen auf spezial eisenbahnwaggons tieflader sagte vander zu die wurden bis ganz nach hinten geschoben die kräne hier die waren zu schwach und hinten brauchte man auch zwei kräne und solch einen großen trafo zu verladen hier überall diese diese tore das war eine teure folgenden von den hallen wieder da kam die woche an die fertig war schalter und transformatoren die kann hiermit mit mit gabelstaplern ein schlepper wurden hier eingeliefert hier wurden sie verpackt transportsicher in</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>[07:25]</strong> kisten und dann mit lkw oder eisenbahn oder schiffsbetrieb verschickt schwierige oder interessante bei diesem gruß trafos waren die hatten ein spezial eisenbahn waren zwei investoren verschickt wurden nach bulgarien nach rumänien nach ungarn schien wehe da musste man vorher die strecke abfahren das macht unser spezial schwertransport ingenieure eisenmann technisch untersuchen sind die brücken hoch genug komme ich dadurch unter umständen musste der zugverkehr insgesamt gesperrt werden weil weil der trafo so breit war dass die zucht eher im gegenteil nicht vorbeifahren ich kann mich erinnern an eine tour einen transport eines trafos nach jugoslawien gerade weg wäre gewesen berlin dresden prag bratislava und so</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>[08:25]</strong> weiter ungarn rumänien bulgarien jugoslawien ging aber nicht wegen dresden sächsische schweiz gebirge das war so dicht an die schienen nach angebaut das man dass man da eben mit dem transformatoren großen nicht vorbei kam der nächste weg wäre gewesen berlin/münchen österreich ungarn und russland ging aber nicht weil die brd dazwischen war die wollte geld das wir nicht hatten wir wollten das berge also haben wir einen riesen umwelt gemacht berlin polen die hohe tatra kann man nicht vorbei muss ganz durch polen durchfahren in die schicht hier ein breites lachen dann wird er die tour ungarn rumänien bulgarien nach st da ist immer drei ingenieure mitgefahren zwei ingenieure die waren verantwortlich</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>[09:26]</strong> für die ladung und ein ingenieur des mit pkw vorne weg gefahren und hat den fahrplan reguliert diese diese diese transporte bekommen einen extra fahrplan durften meistens nur in der rundenzeit fahren also nachts fahren und am tag wurden irgendwo irgendwo anders abgestellt auch wieder interessant an der trauung oder abgestellt am transport und acht stunden später stand der traf plötzlich inhalten meter tiefer da war das unterbleibt sowieso schwer 200 tonnen fast einen halben meter abgesackt ist war und bin TROjaner mit leib und seele und ich glaube die meisten waren das hier könnte kann das gar nicht beschreiben beschreiben alle waren für alle da und alle waren</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>[10:26]</strong> für einen da alle haben sich gegenseitig geholfen dass wir einen zusammenhalt wie eine richtige ich sagte ja circa 5.000 personen wie familie mit ein wenn wir alles agieren alle betriebe ist auch mal übertrieben jetzt 50.000 alle weg wow effekt beim Elektroholz veredelung alles was ihr noch dranhängen schade am meisten hat mich geärgert kw hier bei uns war es eigentlich klar dass der betrieb pleite geht weil wir hatten unsere eigene technologie und die brd auch wieder ihre eigene und warum soll man unter übernehmen wenn man schon eigenheit dass wird würde ich auch noch einen sehen hätte man zwar am besten können aber hat man nicht gemacht alle akw stillzulegen das fand ich sowas von dämlich da wurden kartoffeln aus köln hier angeklagt und</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>[11:28]</strong> bei kaffee oder albern ich hatte das glück transportabteilung für gesagt wir hatten arbeit bis zum schluss hier im betrieb dann haben wir dann sofort selbständig gemacht und hatten auch da wieder arbeiten die DDR hatte verpflichtungen gegenüber anderen ländern wir hatten zum beispiel handelsvertrag mit damals noch sowjetunion über 200.000 kühlschränke sie wurden fertiggestellt und mussten dann hin transportiert werden und durch unsere beziehungen haben wir diesen auftrag erhalten und das hat uns den ersten schub geben 200.000 kühlschränke mit den lkws die wir hatten die hna 3a sie waren für solche langstrecken die behaupten ausgelegt aber wir haben sie hat mir keinen anderen</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>[12:28]</strong> wir haben die sind mit den gefahren außerdem habe ich dann irgendwann mal dann zehn lkws mitfahrer von damit droht die zeit gegangen die gab&#039;s nicht mehr aus gekauft und diese hatten auch hat er diesen auch mit diesem hat er stefan die DDR-produktion behält besteht für afrika auch diese lkws solche großen toren waren die ähnlich gewohnt und die haben wir zu schrott gefahren aber wir haben das geld eingespielt dass wir brauchten ohne dass dies ohne dass wir kredite aufnehmen mussten oder so und kommt man später nach ganz kurzer zeit einig eine große lkws kaufen mit denen von heute</p>\n<!-- /wp:paragraph -->','Dieter Scholz','Dieter Scholz, TRO – nach der Wende OBS – Eisenbahner, 1969 -1999','publish','closed','closed','','dieter-scholz','','','2026-06-03 06:16:51','2026-06-03 04:16:51','',0,'/?post_type=video&#038;p=13378',0,'video','',0),
(13379,0,'2026-05-03 09:24:31','2026-05-03 07:24:31','<!-- wp:paragraph -->\n<p><strong>[00:12]</strong> wir haben einmal gesammelt historische Bauelemente die nicht mehr in der Produktion waren die irgendwo noch lagerten lagerten tischkästen als Erinnerung weil derjenige damit zu tun hatte die Dinge haben wir einen gesammelt und wir haben aus der laufenden Fertigung auch hier ist eingesammelt Stücke um Nachweis zu machen über das Produktionsprofil nicht wir hatten ja also röhrenindustrie einmal ganz pauschal gesagt mit all den röhrenfamilien die es gibt denn die Halbleiterindustrie die bei uns hier auch zum Teil waren war denn die LEDs die Licht im Winter die oben und die Displays dazu und auch der Bereich Flüssigkristalle aber wir waren noch DDR gewesen und äh eine Reihe Leute im Hause die also das gleiche Interesse hatten und diese förderten dass wir also irgendwo unterkommen und das Problem Mann zu finden da schickte es sich dass der gesamte Turm hier von außen</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>[01:09]</strong> kontrolliert werden musste geputzt Fenster und solche Sachen und bei dieser Gelegenheit wurde dieser Raum hier oben dieser Galerie Raum hergerichtet für unsere ausstellungsbedürfnisse hierzu muss man aber historisch sagen der Raum sah damals als wir ihn erst einmal hier besichtigen konnten schlimm aus da waren hier rüber aufgelegt bohlenfläche und es waren so Räume abgeteilt provisorisch warum das war der Aufenthaltsraum von schlagsoldaten denn diese Soldaten hatten hier oben feelings Flugabwehrkanone zu bedienen und wenn also kein Filialen haben müssen die irgendwo bleiben und diese legte dieser räumlichen räumlichen Anordnung die sind geblieben inzwischen waren die Fenster kaputt die Tauben waren große Berge von Toten Tauben es war eine Idee Angelegenheit so und dann hat man</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>[02:12]</strong> hier sozusagen als schwarz Investition Investition ohne ohne öffentliche nebenjunge diese Geschichte zunächst mal ein Hinweis auf den Bauern gehen und Essen architektin und dieser Bau war von der AEG in der Advent Advent Finger an diese Produktion war hier zu eng und da hat man also angefangen während des Ersten Weltkrieges 1915 dieses Haus hier zu bauen mit für die Autoproduktion ging 1934 zu Ende da spielten verschiedene wirtschaftliche Umstände eine Rolle man hat es die man damals die baute die Waren zu teuer und dann war Schluss Schluss 1934 war erstmal hier Schluss und</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>[03:14]</strong> 38 zog die AG mit den mit ihren Röhrenwerken die hatten also an verschiedenen Stellen in der Stadt also hier was da was aber alles so kleine Betriebe die wohnen hier konzentriert war auch im Vorfeld der Rüstung weiterer Weltkrieg spielt durch den Krieg in Deutsch mit Ende des Krieges war wie überall wunderbar von hier erstmal Demontage statt wurde vieles also weggefahren und auf Sammelplätzen um nicht also abzutransportieren dann ja später aber schon kam der Begriff OSW oder spreeberg dieser Begriff Oberspreewald der hat sich also sehr lange erhalten und wechselte dann über als dieser ssrg Betrieb habe ich noch gar nicht erwähnt sowjetischer Aktiengesellschaft dieser SRG Betrieb in Volkes Hand übergeben worden 1952</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>[04:18]</strong> und damit kam auch ein neuer Name Werk für fernmelderwesen denn hier war nicht nur die Hörner das dreiein drin nachher war auch das fernmelden also Telefontechnik und Übertragung waren auch Relikte die aus AEG-zeiten stammen von dem man sich da dann später wieder getrennt hat und zwar Ende 1959 60 wurde und wir hatten aber jetzt das Logo bfund behalten für fernsehelektronik war auch so weit richtig weil wir ja zu jener Zeit also um 1952 in Europa der größte betreuenbergbahn aber nur in dieser Zeit und das waren damals runde Bildröhren für den Fernsehempfänger Leningrad und Fernsehempfänger Rembrandt der reemann war ja für deutsche Publikum gedacht der Leningrad</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>[05:19]</strong> zunächst als operationsgut für die Sowjetunion und wir mussten die gesamten röhrensatz dazu liefern sowohl die Empfänger hören als ob die Bild also wir ungefähr 88 89 hatten wir dieses hier eröffnen können also ein zwei Jahre drei Jahre etwa vorher schon gesammelt und dann ist 89 im Frühjahr muss das gewesen sein ist das denn hier eröffnet worden und Besucher waren einmal die Leute von draußen wir fahren aber auch Leute die wir hier aus dem Hause das war ja auch eine Selbstdarstellung weil es hier ihre erste Form und nach der Wende gab es denn also Besucher durch Öffentlichkeitsarbeit in Zeitung dass man sagt da ist sowas und da kam regelmäßig Leute so dass wir hier also über AWM stellen zwei Personen immer</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>[06:19]</strong> irgendwie verfügbar fahren müssen um die durchzuführen und den Geschichten zu erzählen und bestimmten Zeitpunkt übernahmen die Firma Samsung koreanisches Unternehmen das Haus und den wurde dies hier also dieses Museum mit seinen Museumsgut in Obhut gegeben hat dann Vertrag gemacht und man nahm damals an die Koreaner die werden also da Interesse haben Image und das also das Weiterleben aber die hatten keinen Sinn für also diese deutsche Technik Geschichte und den Mann Röhren Elektronen fremd und seitdem ist das alles eingelagert und existiert noch so und in der Folgezeit ist dann Interesse aus von Leuten hier kommen die hier im Hause sich ausgerundet hatten die Firma nennt sich silikonsensor und die haben den Bestand seit kurzem übernommen wie die Fahrt weitergeht ist</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>[07:21]</strong> heute noch unbekannt</p>\n<!-- /wp:paragraph -->','Mueller WF','Winfried Müller, WF, Ingenieur im Bereich Anwendungstechnik, 1958 – 1990','publish','closed','closed','','mueller-wf','',''