START TRANSACTION;

-- Remove DB overrides for templates/parts now owned by Git-tracked theme files.
DELETE r FROM wp_posts r INNER JOIN wp_posts p ON r.post_parent = p.ID WHERE r.post_type = 'revision' AND p.post_type IN ('wp_template','wp_template_part') AND ((p.post_type = 'wp_template' AND p.post_name IN ('front-page','page-salon-vermietung','page-fuehrungen','page-ueber-uns','page-veranstaltungen','page-ausstellungen','page-videos')) OR (p.post_type = 'wp_template_part' AND p.post_name IN ('footer')));
DELETE FROM wp_posts WHERE post_type IN ('wp_template','wp_template_part') AND ((post_type = 'wp_template' AND post_name IN ('front-page','page-salon-vermietung','page-fuehrungen','page-ueber-uns','page-veranstaltungen','page-ausstellungen','page-videos')) OR (post_type = 'wp_template_part' AND post_name IN ('footer')));

